#ifdef CJK_ENABLE

inline int findCJKCharIndex(uint16_t unicode)
{
    int left = 0;
    int right = CJK_CHAR_COUNT - 1;

    while (left <= right) {
        int mid = (left + right) / 2;
        uint16_t midChar = pgm_read_word(&cjk_char_map[mid]);

        if (midChar == unicode) {
            return mid;
        } else if (midChar < unicode) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

inline bool isCJKChar(uint16_t unicode)
{
    return findCJKCharIndex(unicode) != -1;
}

inline bool isSymbol(uint16_t unicode)
{
    if (unicode <= 127) {
        return true;
    } else {
        return false;
    }
}

inline const uint8_t *getCJKCharBitmap(uint16_t unicode)
{
    int index = findCJKCharIndex(unicode);
    if (index == -1)
        return nullptr;

    return &cjk_font_data[index * CJK_BYTES_PER_CHAR];
}

#endif
